"use client";

import { motion } from "framer-motion";
import Link from "next/link";
import { ArrowRight, Laptop, Megaphone, Cloud, Code2, Globe, Database } from "lucide-react";
import { cn } from "@/lib/utils";

const services = [
  {
    id: "web-development",
    title: "Web Development",
    description: "Custom, scalable web applications built with modern technologies like Next.js and TypeScript.",
    icon: Laptop,
    color: "from-blue-500/20 to-cyan-500/20",
    glow: "bg-blue-500/10",
  },
  {
    id: "digital-marketing",
    title: "Digital Marketing",
    description: "Data-driven marketing strategies to boost your online visibility and conversion rates.",
    icon: Megaphone,
    color: "from-purple-500/20 to-pink-500/20",
    glow: "bg-purple-500/10",
  },
  {
    id: "cloud-hosting",
    title: "Cloud Hosting",
    description: "High-performance and secure cloud solutions tailored for your business needs.",
    icon: Cloud,
    color: "from-indigo-500/20 to-blue-500/20",
    glow: "bg-indigo-500/10",
  },
];

export default function ServicesOverview() {
  return (
    <section className="section-padding px-6 md:px-16 relative bg-[#030303] overflow-hidden">
      {/* Background Glow */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1000px] h-[500px] bg-primary/5 blur-[150px] rounded-full pointer-events-none" />

      <div className="max-w-7xl mx-auto relative z-10">
        <div className="text-center mb-24">
          <h2 className="text-4xl md:text-6xl font-black text-white mb-6 font-outfit tracking-tighter">
            Web Brand Our Services
          </h2>
          <div className="w-24 h-1.5 bg-primary mx-auto rounded-full" />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 lg:gap-16">
          {services.map((service, index) => (
            <motion.div 
              key={service.id}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: index * 0.1 }}
              viewport={{ once: true }}
              className="group relative"
            >
              {/* Card Surface */}
              <div className="relative glass p-10 md:p-14 rounded-[3rem] border-white/5 bg-white/[0.02] hover:bg-white/[0.04] transition-all duration-500 flex flex-col items-center text-center group-hover:border-primary/20 group-hover:translate-y-[-8px]">
                
                {/* Glow Effect */}
                <div className={cn(
                  "absolute inset-0 blur-3xl rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none -z-10",
                  service.glow
                )} />

                {/* Icon Visualization (Inspired by the glowing laptop image) */}
                <div className="relative w-40 h-40 mb-12 flex items-center justify-center">
                   <div className={cn("absolute inset-0 blur-2xl rounded-full", service.glow)} />
                   <div className="relative z-10 w-full h-full bg-gradient-to-br from-white/10 to-transparent rounded-[2.5rem] border border-white/10 flex items-center justify-center shadow-2xl group-hover:scale-110 transition-transform duration-500 overflow-hidden">
                      <service.icon className="w-16 h-16 text-white group-hover:text-primary transition-colors" />
                      
                      {/* Decorative small icons */}
                      <div className="absolute top-4 right-4 w-6 h-6 bg-white/5 rounded-lg border border-white/10 flex items-center justify-center">
                         <Code2 className="w-3 h-3 text-white/40" />
                      </div>
                      <div className="absolute bottom-6 left-6 w-8 h-8 bg-white/5 rounded-xl border border-white/10 flex items-center justify-center">
                         <Database className="w-4 h-4 text-white/40" />
                      </div>
                   </div>
                </div>

                <h3 className="text-3xl font-black text-white mb-6 font-outfit tracking-tight uppercase">
                  {service.title}
                </h3>
                <p className="text-white/40 text-lg leading-relaxed mb-12">
                  {service.description}
                </p>

                <Link 
                  href={`/services#${service.id}`}
                  className="px-10 py-5 bg-white/5 border border-white/10 text-white rounded-2xl font-black text-sm flex items-center gap-3 group-hover:bg-primary group-hover:border-primary group-hover:text-white transition-all"
                >
                  Learn More <ArrowRight className="w-4 h-4" />
                </Link>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
