"use client";

import Hero from "@/components/sections/Hero";
import ExpertCommunity from "@/components/sections/ExpertCommunity";
import ServicesOverview from "@/components/sections/ServicesOverview";
import FeaturedProjects from "@/components/sections/FeaturedProjects";
import Testimonials from "@/components/sections/Testimonials";
import FAQPreview from "@/components/sections/FAQPreview";
import TrustSection from "@/components/sections/TrustSection";
import FinalCTA from "@/components/sections/FinalCTA";
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import AnoAI from "@/components/ui/animated-shader-background";

export default function Home() {
  return (
    <>
      <AnoAI />
      <Hero />
      <ExpertCommunity />
      <ServicesOverview />
      <FeaturedProjects />
      
      {/* Blog Highlights Section */}
      <section className="section-padding px-8 md:px-16 bg-background relative overflow-hidden border-t border-border/40">
        <div className="max-w-7xl mx-auto">
          <div className="flex flex-col md:flex-row justify-between items-end mb-32 gap-10">
            <div className="max-w-2xl">
              <h2 className="text-4xl md:text-5xl lg:text-7xl font-black text-white mb-10 font-outfit tracking-tight leading-[1.1]">
                Latest from the <br />
                <span className="text-gradient">Collective Blog.</span>
              </h2>
              <p className="text-foreground/60 text-lg md:text-2xl leading-relaxed max-w-2xl">
                Insights on building high-performance applications, SaaS growth, 
                and modern design systems.
              </p>
            </div>
            <Link 
              href="/blogs" 
              className="flex items-center gap-2 text-primary font-semibold hover:gap-4 transition-all pb-6"
            >
              Read All Articles <ArrowRight className="w-5 h-5" />
            </Link>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-10 lg:gap-12">
            {[
              {
                title: "How We Build High-Performance Next.js Applications That Scale",
                category: "Engineering",
                date: "Oct 12, 2024",
                slug: "high-performance-nextjs",
              },
              {
                title: "From Idea to MVP: Our Startup Development Framework",
                category: "Startup Strategy",
                date: "Oct 05, 2024",
                slug: "startup-mvp-framework",
              },
              {
                title: "Designing for Conversions: UI Decisions That Increase Revenue",
                category: "UI/UX Design",
                date: "Sep 28, 2024",
                slug: "designing-for-conversions",
              }
            ].map((blog, idx) => (
              <Link 
                key={idx}
                href={`/blogs/${blog.slug}`}
                className="group glass p-8 rounded-3xl hover:border-primary/50 transition-all"
              >
                <p className="text-primary text-[10px] uppercase tracking-widest font-bold mb-4">
                  {blog.category} • {blog.date}
                </p>
                <h3 className="text-xl font-bold text-white mb-6 font-outfit group-hover:text-primary transition-colors leading-tight">
                  {blog.title}
                </h3>
                <div className="flex items-center gap-2 text-white/40 text-sm group-hover:text-white transition-colors">
                  Read Article <ArrowRight className="w-4 h-4" />
                </div>
              </Link>
            ))}
          </div>
        </div>
      </section>

      <Testimonials />
      <FAQPreview />
      <TrustSection />
      <FinalCTA />
    </>
  );
}
