"use client";

import Link from "next/link";
import { ArrowRight, ExternalLink } from "lucide-react";
import { projects } from "@/data/projects";
import { cn } from "@/lib/utils";

export default function FeaturedProjects() {
  return (
    <section className="section-padding px-8 md:px-16 bg-background relative overflow-hidden">
      <div className="max-w-7xl mx-auto">
        <div className="flex flex-col md:flex-row justify-between items-end mb-32 gap-10">
          <div className="max-w-2xl">
            <h2 className="text-4xl md:text-5xl lg:text-7xl font-black text-white mb-10 font-outfit tracking-tight leading-[1.1]">
              Featured <br />
              <span className="text-gradient">Case Studies.</span>
            </h2>
            <p className="text-foreground/60 text-lg md:text-2xl leading-relaxed max-w-2xl">
              Explore how we've helped startups and established companies 
              build scalable digital solutions that drive results.
            </p>
          </div>
          <Link 
            href="/projects" 
            className="group flex items-center gap-2 text-primary font-semibold hover:gap-4 transition-all pb-6"
          >
            View All Projects <ArrowRight className="w-5 h-5" />
          </Link>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 lg:gap-24">
          {projects.slice(0, 4).map((project, index) => (
            <div 
              key={project.id}
              className="group relative overflow-hidden rounded-[2.5rem] bg-muted/30 border border-border/40 hover:border-primary/50 transition-all duration-700"
            >
              {/* Image Container */}
              <div className="aspect-[16/10] overflow-hidden relative">
                <img 
                  src={project.thumbnail} 
                  alt={project.title}
                  className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-background via-background/20 to-transparent opacity-80" />
                
                {/* Overlay with Meta */}
                <div className="absolute top-8 right-8 flex gap-2">
                  {project.tags.map(tag => (
                    <span key={tag} className="px-3 py-1 bg-black/40 backdrop-blur-md border border-white/10 rounded-full text-[10px] uppercase tracking-widest text-white/80 font-bold">
                      {tag}
                    </span>
                  ))}
                </div>
              </div>

              {/* Content */}
              <div className="p-8 md:p-12">
                <p className="text-primary text-xs font-bold uppercase tracking-[0.2em] mb-4">
                  {project.category}
                </p>
                <h3 className="text-3xl font-bold text-white mb-4 font-outfit group-hover:text-primary transition-colors">
                  {project.title}
                </h3>
                <p className="text-foreground/60 text-base leading-relaxed mb-8 max-w-lg">
                  {project.description}
                </p>
                
                <div className="flex items-center gap-6">
                  <Link 
                    href={`/projects/${project.slug}`}
                    className="flex items-center gap-2 text-white font-bold text-sm hover:text-primary transition-colors"
                  >
                    View Details <ArrowRight className="w-4 h-4" />
                  </Link>
                  <Link 
                    href="#"
                    className="flex items-center gap-2 text-foreground/40 font-bold text-sm hover:text-white transition-colors"
                  >
                    Live Demo <ExternalLink className="w-4 h-4" />
                  </Link>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
